void testUuid();

void testUuid()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    // uuid() - standard UUID v4: xxxxxxxx-xxxx-4xxx-[89ab]xxx-xxxxxxxxxxxx
    std::any id1 = exchange.uuid(); // need type for .length understanding
    std::any id2 = exchange.uuid();
    assertTrue(!isEqual(id1, std::any{}), std::string("uuid 1 must return a value"));
    assertTrue(!isEqual(id2, std::any{}), std::string("uuid 2 must return a value"));
    assertTrue(!isEqual(id1, id2), std::string("uuid() must return unique values on each call"));
    assertTrue(isEqual(toString(id1), id1), std::string("uuid() must return a string"));
    assertTrue(isEqual(toString(id2), id2), std::string("uuid() must return a string"));
    assertTrue(isEqual(getStringLength(id1), 36), add(std::string("uuid() must return a 36-character string, returned id1: "), id1));
    assertTrue(isEqual(getStringLength(id2), 36), add(std::string("uuid() must return a 36-character string, returned id2: "), id2));
    assertTrue(isEqual(getIndexOf(id1, std::string("-")), 8), add(std::string("uuid() must have dash, returned id1: "), id1));
    // uuid16() - 16-char hex string
    std::any id16a = exchange.uuid16();
    std::any id16b = exchange.uuid16();
    assertTrue(!isEqual(id16a, std::any{}), std::string("uuid16 1 must return a value"));
    assertTrue(!isEqual(id16b, std::any{}), std::string("uuid16 2 must return a value"));
    assertTrue(!isEqual(id16a, id16b), add(add(add(std::string("uuid16() must return unique values on each call, returned id16a: "), id16a), std::string(", id16b: ")), id16b));
    assertTrue(isEqual(toString(id16a), id16a), add(std::string("uuid16() must return a string, returned id16a: "), id16a));
    assertTrue(isEqual(toString(id16b), id16b), add(std::string("uuid16() must return a string, returned id16b: "), id16b));
    assertTrue(isEqual(getStringLength(id16a), 16), add(std::string("uuid16() must return a 16-character string, returned id16a: "), id16a));
    assertTrue(isEqual(getStringLength(id16b), 16), add(std::string("uuid16() must return a 16-character string, returned id16b: "), id16b));
    // uuid22() - 22-char hex string
    std::any id22a = exchange.uuid22();
    std::any id22b = exchange.uuid22();
    assertTrue(!isEqual(id22a, std::any{}), std::string("uuid22 1 must return a value"));
    assertTrue(!isEqual(id22b, std::any{}), std::string("uuid22 2 must return a value"));
    assertTrue(!isEqual(id22a, id22b), std::string("uuid22() must return unique values on each call"));
    assertTrue(isEqual(toString(id22a), id22a), add(std::string("uuid22() must return a string, returned id22a: "), id22a));
    assertTrue(isEqual(toString(id22b), id22b), add(std::string("uuid22() must return a string, returned id22b: "), id22b));
    assertTrue(isEqual(getStringLength(id22a), 22), add(std::string("uuid22() must return a 22-character string, returned id22a: "), id22a));
    assertTrue(isEqual(getStringLength(id22b), 22), add(std::string("uuid22() must return a 22-character string, returned id22b: "), id22b));
}

